class Solution:
 def areNumbersAscending(self,s):
  nums=[int(w) for w in s.split() if w.isdigit()]
  return all(a<b for a,b in zip(nums,nums[1:]))

from collections import Counter
class Solution:
 def kthDistinct(self,arr,k):
  c=Counter(arr)
  for x in arr:
   if c[x]==1:
    k-=1
    if k==0:return x
  return ''

