class Solution:
 def countVowelSubstrings(self,word):
  vowels=set('aeiou');ans=0
  for i in range(len(word)):
   seen=set()
   for j in range(i,len(word)):
    if word[j] not in vowels:break
    seen.add(word[j])
    if len(seen)==5:ans+=1
  return ans

from collections import Counter
class Solution:
 def countWords(self,words1,words2):
  a=Counter(words1);b=Counter(words2)
  return sum(a[x]==b[x]==1 for x in a)

class Solution:
 def findEvenNumbers(self,digits):
  from itertools import permutations
  return sorted({int(''.join(map(str,p))) for p in permutations(digits,3) if p[0]!=0 and p[2]%2==0})

class Solution:
 def countPoints(self,rings):
  rods=[set() for _ in range(10)]
  for i in range(0,len(rings),2):rods[int(rings[i+1])].add(rings[i])
  return sum(len(s)==3 for s in rods)
